/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import gsortinsBy = require( './index' );


// FUNCTIONS //

/**
* Callback function.
*
* @param a - first value
* @param b - second value
* @returns comparison result
*/
function clbk( a: number, b: number ): number {
	if ( a < b ) {
		return -1;
	}
	if ( a > b ) {
		return 1;
	}
	return 0;
}


// TESTS //

// The function returns a collection...
{
	const x = new Float64Array( 10 );

	gsortinsBy( x.length, x, 1, clbk ); // $ExpectType Float64Array
	gsortinsBy( x.length, new AccessorArray( x ), 1, clbk ); // $ExpectType AccessorArray<number>

	gsortinsBy( x.length, x, 1, clbk, {} ); // $ExpectType Float64Array
	gsortinsBy( x.length, new AccessorArray( x ), 1, clbk, {} ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsortinsBy( '10', x, 1, clbk ); // $ExpectError
	gsortinsBy( true, x, 1, clbk ); // $ExpectError
	gsortinsBy( false, x, 1, clbk ); // $ExpectError
	gsortinsBy( null, x, 1, clbk ); // $ExpectError
	gsortinsBy( undefined, x, 1, clbk ); // $ExpectError
	gsortinsBy( [], x, 1, clbk ); // $ExpectError
	gsortinsBy( {}, x, 1, clbk ); // $ExpectError
	gsortinsBy( ( x: number ): number => x, x, 1, clbk ); // $ExpectError

	gsortinsBy( '10', x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( true, x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( false, x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( null, x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( undefined, x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( [], x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( {}, x, 1, clbk, {} ); // $ExpectError
	gsortinsBy( ( x: number ): number => x, x, 1, clbk, {} ); // $ExpectError
}

