	gsortinsBy( 10, ( x: number ): number => x, 1, clbk ); // $ExpectError

	gsortinsBy( 10, 10, 1, clbk, {} ); // $ExpectError
	gsortinsBy( 10, '10', 1, clbk, {} ); // $ExpectError
	gsortinsBy( 10, true, 1, clbk, {} ); // $ExpectError
