// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );

	gsortinsBy(); // $ExpectError
	gsortinsBy( x.length ); // $ExpectError
	gsortinsBy( x.length, x ); // $ExpectError
	gsortinsBy( x.length, x, 1 ); // $ExpectError
	gsortinsBy( x.length, x, 1, clbk, {}, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a collection...
{
	const x = new Float64Array( 10 );

	gsortinsBy.ndarray( x.length, x, 1, 0, clbk ); // $ExpectType Float64Array
	gsortinsBy.ndarray( x.length, new AccessorArray( x ), 1, 0, clbk ); // $ExpectType AccessorArray<number>

	gsortinsBy.ndarray( x.length, x, 1, 0, clbk, {} ); // $ExpectType Float64Array
	gsortinsBy.ndarray( x.length, new AccessorArray( x ), 1, 0, clbk, {} ); // $ExpectType AccessorArray<number>
}

